#!/bin/bash
set -euo pipefail

LOG="/var/log/nginx/custom_access.log"
OUT="/tmp/error_report.txt"

if [[ ! -r "$LOG" ]]; then
    echo "ABSTAIN: файл $LOG не существует или недоступен для чтения" >&2
    exit 1
fi

# Предполагается стандартный формат combined: IP — первое поле, статус — 9-е поле.
awk '
{
    ip = $1
    status = $9
    if (status ~ /^[0-9]+$/ && ((status >= 400 && status <= 599) && status != 404)) {
        count[ip]++
    }
}
END {
    for (ip in count) {
        print count[ip], ip
    }
}
' "$LOG" | sort -k1,1nr -k2,2 > "$OUT"

echo "Отчёт сохранён в $OUT"
