#!/bin/bash
set -uo pipefail

F=/etc/nginx/sites-enabled/api.conf
B="${F}.bak.$(date +%s)"
HAD_ORIG=0

if [ -f "$F" ]; then
    cp -a "$F" "$B" || { echo "Не удалось создать резервную копию" >&2; exit 1; }
    HAD_ORIG=1
fi

cat > "$F" <<'EOF'
server {
    listen 80;
    server_name _;

    # Проксирование /v1/users без обрезки префикса /v1/
    # (без URI в proxy_pass запрос передаётся как есть)
    location /v1/users {
        proxy_pass http://127.0.0.1:9000;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }

    # /status доступен только с 127.0.0.1
    location = /status {
        allow 127.0.0.1;
        deny all;
        proxy_pass http://127.0.0.1:9000;
        proxy_set_header Host $host;
    }
}
EOF

if nginx -t; then
    echo "Конфигурация корректна: $F"
    exit 0
else
    echo "nginx -t не прошёл, откат изменений" >&2
    if [ "$HAD_ORIG" -eq 1 ]; then
        cp -a "$B" "$F"
    else
        rm -f "$F"
    fi
    exit 1
fi
