#!/bin/bash
set -euo pipefail

DIR="/etc/app/nodes"
OUT="/tmp/duplicates.txt"

if [ ! -d "$DIR" ]; then
    echo "Директория $DIR не найдена" >&2
    exit 1
fi

find "$DIR" -type f -print0 \
  | xargs -0 sha256sum \
  | sort \
  | awk '
    {
      hash = $1
      path = substr($0, index($0, $2))
      count[hash]++
      paths[hash] = paths[hash] "\n" path
    }
    END {
      for (h in count) {
        if (count[h] > 1) print substr(paths[h], 2)
      }
    }' \
  | sort \
  > "$OUT"

echo "Готово: $(wc -l < "$OUT") дублирующихся путей записано в $OUT"

